  /* ---------------------------------------------------------------- 左侧三卡 */
  /** 底部两张卡的真实高度 → CSS 变量，卡一据此收住，避免互相盖住 */
  function syncCardsHeight() {
    var col = document.getElementById('dbf-sidebar');
    if (!col) return;
    var box = col.getBoundingClientRect();
    if (box.height > 0) {
      document.documentElement.style.setProperty('--dbf-cards-h', Math.ceil(box.height) + 'px');
    }
  }

